namespace app_desktop.Services.Warp;

internal static class WarpInstallHtmlBuilder
{
	internal static string BuildDocument()
	{
		return "<!doctype html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src https://nestg-assets.local; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'\">\n<title>NestG — Cài Cloudflare WARP</title>\n<style>\n:root { color-scheme: dark; font-family: 'Segoe UI Variable Text', 'Segoe UI', sans-serif; color: #f3f7fb; background: #0d141e; }\n* { box-sizing: border-box; }\nhtml, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }\nbutton { font: inherit; cursor: pointer; }\nbutton:focus-visible { outline: 2px solid #8fd3ff; outline-offset: 3px; }\nbutton:disabled { cursor: default; opacity: .48; }\n[hidden] { display: none !important; }\n.window { display: grid; grid-template-rows: 58px minmax(0, 1fr) auto; width: 100%; height: 100%; overflow: hidden; border: 1px solid #34495e; border-radius: 14px; background: radial-gradient(ellipse 80% 55% at 90% 4%, #1b3144 0%, transparent 72%), #0d141e; }\n.titlebar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0 18px 0 24px; border-bottom: 1px solid #ffffff0d; user-select: none; }\n.brand { display: flex; align-items: center; gap: 11px; min-width: 0; font-size: 18px; font-weight: 700; letter-spacing: -.3px; }\n.brand img { width: 26px; height: 32px; object-fit: contain; }\n.titlebar-note { margin-left: 10px; padding-left: 14px; border-left: 1px solid #3a4b5c; color: #9fb3c6; font-size: 12px; font-weight: 500; letter-spacing: 0; white-space: nowrap; }\n.close-icon { display: grid; place-items: center; flex: 0 0 40px; width: 40px; height: 40px; padding: 0; border: 0; border-radius: 9px; background: transparent; color: #b4c5d5; }\n.close-icon:hover:not(:disabled) { background: #26394a; color: #fff; }\n.close-icon svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; }\nmain { min-height: 0; padding: 25px 30px 22px; overflow: auto; scrollbar-gutter: stable; }\n.hero { display: flex; gap: 20px; align-items: flex-start; margin-bottom: 23px; }\n.warp-symbol { display: grid; place-items: center; flex: 0 0 72px; width: 72px; height: 72px; border: 1px solid #ff9d4a63; border-radius: 18px; background: linear-gradient(150deg, #3d271d, #241e20); box-shadow: inset 0 1px #ffffff14, 0 10px 30px #f3802012; }\n.warp-symbol svg { width: 40px; height: 40px; fill: none; stroke: #ff9d48; stroke-width: 1.65; stroke-linecap: round; stroke-linejoin: round; }\n.eyebrow { margin: 2px 0 5px; color: #ffa965; font-size: 11px; font-weight: 750; letter-spacing: 1.5px; }\nh1 { margin: 0; font-size: 29px; line-height: 1.23; letter-spacing: -.8px; font-weight: 700; }\n.intro { margin: 9px 0 0; color: #b9cad8; font-size: 14px; line-height: 1.5; }\n.status-card { position: relative; padding: 17px 18px; border: 1px solid #355168; border-radius: 12px; background: #142637; }\n.status-top { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }\n.status-dot { width: 8px; height: 8px; flex: 0 0 8px; border-radius: 50%; background: #82badc; box-shadow: 0 0 0 4px #82badc18; }\n.status-title { font-size: 13px; font-weight: 700; color: #d7e9f8; }\n.status-copy { margin: 0 0 0 18px; color: #aecaDF; font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }\n.status-card[data-stage=\"ready\"] { border-color: #357b70; background: #16352f; }\n.status-card[data-stage=\"ready\"] .status-dot { background: #77d8bd; }\n.status-card[data-stage=\"failed\"], .status-card[data-stage=\"cancelled\"] { border-color: #845c57; background: #302421; }\n.status-card[data-stage=\"failed\"] .status-dot, .status-card[data-stage=\"cancelled\"] .status-dot { background: #f2a59a; }\n.status-card[data-stage=\"needsSetup\"], .status-card[data-stage=\"needsRestart\"] { border-color: #906f40; background: #342a1d; }\n.status-card[data-stage=\"needsSetup\"] .status-dot, .status-card[data-stage=\"needsRestart\"] .status-dot { background: #efc27e; }\n.progress-row { display: flex; align-items: center; gap: 12px; margin-top: 15px; }\n.progress-track { flex: 1; height: 5px; overflow: hidden; border-radius: 5px; background: #07131d; }\n.progress-fill { height: 100%; width: 0; border-radius: inherit; background: linear-gradient(90deg, #6cb6e8, #a7d8f5); transition: width .15s ease; }\n.progress-row[data-indeterminate=\"true\"] .progress-fill { width: 32% !important; animation: glide 1.4s ease-in-out infinite alternate; }\n.progress-percent { min-width: 34px; text-align: right; color: #afc7d9; font-size: 12px; font-variant-numeric: tabular-nums; }\n@keyframes glide { from { transform: translateX(-100%); } to { transform: translateX(300%); } }\n.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 17px; }\n.detail { display: flex; gap: 11px; padding: 13px 14px; border: 1px solid #2b3c4c; border-radius: 10px; background: #13202c; }\n.detail svg { width: 18px; height: 18px; flex: 0 0 18px; margin-top: 1px; fill: none; stroke: #89b9d7; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.detail strong { display: block; margin-bottom: 3px; color: #ecf4fa; font-size: 12px; font-weight: 700; }\n.detail p { margin: 0; color: #aebfcd; font-size: 12px; line-height: 1.45; }\n.error { margin: 12px 0 0; color: #f4b0a7; font-size: 12px; }\nfooter { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 15px 24px; border-top: 1px solid #283d4e; background: #111f2b; }\n.help { min-height: 42px; padding: 0 8px; border: 0; background: transparent; color: #acd4ef; font-size: 12px; font-weight: 650; white-space: nowrap; }\n.help:hover { color: #fff; text-decoration: underline; }\n.actions { display: flex; gap: 9px; align-items: center; justify-content: flex-end; flex-wrap: wrap; }\n.actions button { min-height: 42px; padding: 0 16px; border-radius: 8px; font-size: 13px; font-weight: 650; white-space: nowrap; }\n.secondary { border: 1px solid #41566b; background: #203246; color: #e8f2fb; }\n.secondary:hover:not(:disabled) { background: #2b445c; }\n.primary { border: 1px solid #77c5f1; background: #68bce9; color: #092638; box-shadow: inset 0 1px #ffffff5c; }\n.primary:hover:not(:disabled) { background: #90d4f5; }\n::-webkit-scrollbar { width: 7px; }\n::-webkit-scrollbar-thumb { background: #3b5569; border-radius: 8px; }\n@media (max-width: 600px) { .titlebar-note { display: none; } main { padding: 20px; } .detail-grid { grid-template-columns: 1fr; } footer { flex-wrap: wrap; padding: 12px 20px; } .help { min-height: 32px; } .actions { width: 100%; } }\n@media (max-width: 420px) { .hero { gap: 12px; } .warp-symbol { flex-basis: 54px; width: 54px; height: 54px; border-radius: 13px; } .warp-symbol svg { width: 31px; height: 31px; } h1 { font-size: 23px; } .intro { font-size: 13px; } .actions button { flex: 1; padding-inline: 9px; } }\n@media (max-height: 430px) { main { padding-top: 14px; padding-bottom: 14px; } .hero { margin-bottom: 14px; } .detail-grid { margin-top: 12px; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; } }\n</style>\n</head>\n<body>\n<section class=\"window\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"install-title\" aria-describedby=\"install-intro\">\n    <header class=\"titlebar\" data-drag>\n        <div class=\"brand\"><img src=\"https://nestg-assets.local/logo.png\" alt=\"\"><span>NestG</span><span class=\"titlebar-note\">Thiết lập kết nối</span></div>\n        <button id=\"window-close\" class=\"close-icon\" type=\"button\" data-action=\"close\" aria-label=\"Đóng cửa sổ cài WARP\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m6 6 12 12M18 6 6 18\"/></svg></button>\n    </header>\n    <main tabindex=\"0\" aria-label=\"Thông tin cài đặt WARP\">\n        <div class=\"hero\">\n            <span class=\"warp-symbol\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\"><path d=\"M12 34h25a7 7 0 0 0 0-14h-2a12 12 0 0 0-23-1 8 8 0 0 0 0 15Z\"/><path d=\"m19 27 4 4 7-8\"/></svg></span>\n            <div><p class=\"eyebrow\">CLOUDFLARE WARP</p><h1 id=\"install-title\">Cài WARP cho máy của bạn</h1><p class=\"intro\" id=\"install-intro\">NestG sẽ tải bộ cài chính thức của Cloudflare và mở trình cài đặt Windows để bạn xác nhận.</p></div>\n        </div>\n        <section class=\"status-card\" id=\"status-card\" data-stage=\"idle\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">\n            <div class=\"status-top\"><span class=\"status-dot\" aria-hidden=\"true\"></span><strong class=\"status-title\" id=\"status-title\">Chưa cài đặt</strong></div>\n            <p class=\"status-copy\" id=\"status-copy\">WARP chưa có trên máy. Kết nối vẫn đang tắt.</p>\n            <div class=\"progress-row\" id=\"progress-row\" hidden><div class=\"progress-track\" role=\"progressbar\" aria-label=\"Tiến độ tải WARP\" aria-valuemin=\"0\" aria-valuemax=\"100\" id=\"progress-track\"><div class=\"progress-fill\" id=\"progress-fill\"></div></div><span class=\"progress-percent\" id=\"progress-percent\"></span></div>\n        </section>\n        <div class=\"detail-grid\">\n            <div class=\"detail\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c-3 3-3 15 0 18M12 3c3 3 3 15 0 18\"/></svg><div><strong>Áp dụng cho cả máy</strong><p>WARP có thể ảnh hưởng đến kết nối Steam và các ứng dụng khác.</p></div></div>\n            <div class=\"detail\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2 4 6v6c0 5 3 8 8 10 5-2 8-5 8-10V6Z\"/><path d=\"m9 12 2 2 4-4\"/></svg><div><strong>Bạn kiểm soát kết nối</strong><p>Windows và Cloudflare có thể hỏi xác nhận. Cài xong, bấm công tắc NestG để kết nối.</p></div></div>\n        </div>\n        <p class=\"error\" id=\"bridge-error\" role=\"alert\" hidden></p>\n    </main>\n    <footer>\n        <button class=\"help\" type=\"button\" data-action=\"help\">Trang Cloudflare ↗</button>\n        <div class=\"actions\"><button id=\"open-cloudflare\" class=\"secondary\" type=\"button\" data-action=\"open\" hidden>Mở Cloudflare</button><button id=\"defer\" class=\"secondary\" type=\"button\" data-action=\"close\">Để sau</button><button id=\"primary\" class=\"primary\" type=\"button\" data-action=\"install\">Tải và cài WARP</button></div>\n    </footer>\n</section>\n<script>\n(() => {\n    const bridge = window.chrome?.webview;\n    const statusCard = document.getElementById('status-card');\n    const title = document.getElementById('status-title');\n    const copy = document.getElementById('status-copy');\n    const progress = document.getElementById('progress-row');\n    const track = document.getElementById('progress-track');\n    const fill = document.getElementById('progress-fill');\n    const percentText = document.getElementById('progress-percent');\n    const primary = document.getElementById('primary');\n    const defer = document.getElementById('defer');\n    const windowClose = document.getElementById('window-close');\n    const cloudflare = document.getElementById('open-cloudflare');\n    function post(action) {\n        try {\n            if (!bridge?.postMessage) throw new Error('Bridge unavailable');\n            if (action === 'install' || action === 'recheck') primary.disabled = true;\n            bridge.postMessage(action);\n        } catch {\n            primary.disabled = true;\n            const error = document.getElementById('bridge-error');\n            error.textContent = 'Không kết nối được với NestG. Đóng cửa sổ và thử lại.';\n            error.hidden = false;\n            defer.focus();\n        }\n    }\n    window.__nestgWarpInstall = {\n        render(state) {\n            statusCard.dataset.stage = state.stage;\n            title.textContent = state.title;\n            copy.textContent = state.message;\n            progress.hidden = !state.showProgress;\n            progress.dataset.indeterminate = state.showProgress && state.percent == null ? 'true' : 'false';\n            fill.style.width = `${Math.max(0, Math.min(100, state.percent ?? 0))}%`;\n            percentText.textContent = state.percent == null ? '' : `${state.percent}%`;\n            if (state.percent == null) track.removeAttribute('aria-valuenow');\n            else track.setAttribute('aria-valuenow', state.percent);\n            primary.textContent = state.primaryLabel;\n            primary.dataset.action = state.primaryAction;\n            primary.disabled = !state.primaryEnabled;\n            defer.textContent = state.closeLabel;\n            defer.disabled = !state.canClose;\n            windowClose.disabled = !state.canClose;\n            cloudflare.hidden = !state.showCloudflare;\n            cloudflare.disabled = state.busy;\n        }\n    };\n    bridge?.addEventListener('message', event => window.__nestgWarpInstall.render(event.data));\n    document.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', () => {\n        if (!button.disabled) post(button.dataset.action);\n    }));\n    document.addEventListener('keydown', event => {\n        if (event.key === 'Escape') { event.preventDefault(); if (!defer.disabled) post('close'); }\n    });\n    document.querySelector('[data-drag]').addEventListener('mousedown', event => {\n        if (event.button === 0 && !event.target.closest('button')) post('window:drag');\n    });\n    defer.focus();\n})();\n</script>\n</body>\n</html>";
	}
}
